ship=("פעם, לפני שנים רבות, יצאה לה ספינה מאחת הארצות. ספינה ענקית, מלאה באוצרות, יפה ומרהיבה מכל הבחינות. ובאחד החדרים נוסע אחד החליט בחדרו לעשות בלאגן, קדח לו חורים בקירות והרעיד את כל הסיפון ללא בעיות.\n"
"הנוסעים האחרים נעשו מודאגים וניסו לשכנעו להפסיק בקידוחים. אך הוא האמין שכל אחד לעצמו - ומה שהוא עושה זה רק עניינו.\n"
"לאט לאט חדרו מים לספינה, ובתוך כמה שעות היתה כבר בריכה. לאחר מספר ימים נעלמו האנשים והספינה המרהיבה במצולות שקעה.")
sticks=("אב אחד עמד למות ולפני מיתתו אסף את כל בניו. לכל אחד מהם הביא בתורו קיסם וביקש מהם שישברו אותו, כולם עשו זאת בהצלחה וללא כל בעיה.\n"
"אח\"כ נתן האב לכל אחד מבניו קבוצת קיסמים וביקש מהם לשבור את הקבוצה הזו, אך אף אחד מהם לא הצליח.\n"
"אמר להם אביהם: כמו הקיסמים, אם תהיו מפורדים, כל דבר, אפילו הדבר הקטן ביותר, יוכל לשבור אתכם. אך אם תהיו מאוחדים ומלוכדים יחדיו, תמיד אף אחד ושום דבר לא יוכל להפריד או לשבור אתכם.")
comm=("היחידים השייכים לקהילה משלימים אלו את אלו.\n"
"בכל אדם יש משהו מיוחד במינו, נדיר, שאינו ידוע לאחרים, לכל אחד יש משהו מיוחד לומר, מיוחד להוסיף לקשת הצבעים הקהילתית. לפיכך, כאשר מצטרף האדם הבודד לקהילה, הוא מוסיף משהו חדש, הוא תורם משהו ששום אדם אחר לא יכול לתרום, הוא מעשיר את הקהילה, אין לו תחליף! היהדות מאז ומתמיד ראתה את היחיד כאילו הוא עולם קטן ובשל אותה המיוחדות מתכנסים בני האדם ביחד, ומשלימים אלו את אלו ..ומושגת אחדות.")
mesilat=("ואין טוב לו לאדם אלא שיבקש לו חברים תמימים, שיאירו עיניו במה שהוא עיוור בו ויוכיחהו באהבתם ונמצאו מצילים אותו מכל רע, כי מה שאין האדם יכול לראות - לפי שאינו רואה חובה לעצמו - האם יראו ויבינו ויזהירוהו ונשמר.")
comp=("המחשב שלנו הוא ממודל ישן, אף על פי כן הוא פועל די טוב, פרט לאחד המקשים שמת.\n"
"יש בו ארבעים וששה מקשים הפועלים באופן המניח את הדעת, אך אחד המקשים אינו פועל ומקלקל את השורה.\n"
"לעתים נראה כאילו העולם כולו פועל כמו המחשב שלנו הזה.\n"
"כלומר, לא כל האנשים שתאמר לעצמך: אין זה משנה שהרי איני אלא אדם אחד, אמנם אני לא עושה כלום, אך גם לא אשבש כלום.\n"
"אלא שבכל זאת יש חשיבות אדירה לדברים שהאדם הבודד עושה. הבסיס לכל צוות או שותפות אמיתית בקהילה, הוא שיתוף פעולה מלא של כל אחד.\n"
"לכן, להבא אם תחשוב שהינך רק אדם אחד, שמאמציו אינם מוסיפים ואינם גורעים, זכור את המחשב שלנו.")
rd=[reading('hole-in-the-ship','חור בספינה',"כיתה ה'-י\"ב",5,12,'נוסע שקודח חור בקיר החדר שלו, ואומר שזה רק עניינו.',ship,'לשאול: מתי ״זה רק עניין שלי״ כשזה לא?',['חברה','אחריות','משל']),
    reading('sticks-unity','כוחנו באחדותנו',"כיתה ג'-י\"ב",3,12,'אב נותן לבניו קיסם בודד וצרור קיסמים, ושואל מה קל לשבור.',sticks,'אפשר להביא קיסמים אמיתיים ולהדגים.',['חברה','אחדות','משל']),
    reading('individuals-complete-each-other','היחידים המשלימים',"כיתה ח'-י\"ב",8,12,'כל אדם מוסיף צבע שאין לאף אחד אחר, ולכן הקהילה זקוקה לכולם.',comm,'לשאול: מה הצבע שלכם בקבוצה?',['חברה','קהילה','הרב קוק'],'הרב קוק',dom='שניהם'),
    reading('mesilat-friends','חברים תמימים',"כיתה ט'-י\"ב",9,12,'מסילת ישרים על חברים שמראים לנו מה אנחנו לא רואים.',mesilat,'לשאול: מי מראה לנו מה אנחנו עיוורים אליו, ואיך מגיבים?',['חברה','חברות','מסילת ישרים'],'מסילת ישרים (הרמח"ל), פרק כ"ב-כ"ג',dom='שניהם'),
    reading('our-computer','המחשב שלנו',"כיתה ו'-י\"ב",6,12,'מחשב ישן עם מקש אחד שמת, ושאלה על מה שיחיד עושה.',comp,'לשאול: איזה ״מקש״ אנחנו בצוות, ומה קורה כשהוא לא עובד?',['חברה','אחריות','משל'])]
content=("א. חור בספינה\n\n"+ship+"\n\nב. כוחנו באחדותנו\n\n"+sticks+"\n\nג. היחידים המשלימים (הרב קוק)\n\n"+comm+"\n\nד. חברים תמימים (מסילת ישרים)\n\n"+mesilat+"\n\nה. המחשב שלנו\n\n"+comp)
st=staff('staff-society-one-and-all','חברה: מה אני מוסיף לקבוצה','חברה',45,'כל צוות ההדרכה',
 'חמישה קטעים על היחיד והקבוצה: חור בספינה, קיסמים, צבעים בקהילה, חברים שמזהירים ומחשב עם מקש אחד שמת.',
 ['הצוות יבין איך מעשה של אחד משפיע על כולם, לטובה ולרעה','כל מדריך יגדיר מה הוא מוסיף לצוות שאף אחד אחר לא מוסיף'],
 'שואלים: ״מה הדבר שרק אתם עושים בצוות הזה, ושאם לא תעשו אותו אף אחד לא יעשה?״',content,
 ['איפה אצלנו מישהו קודח חור בחדר שלו ואומר ״זה רק עניין שלי״?','מה ה״צבע״ שלי בצוות, ומה חסר כשאני לא כאן?','איך נותנים ומקבלים תוכחה מחבר ״תמים״ בלי שזה יפגע?'],
 'כל מדריך כותב משפט שיגיד לחבר צוות אחד על מה שהוא מוסיף לצוות.')
